Section Ret.
Variables (p : dlp) (j : list byte) (b : Z) (ib : nat) (ents : list (Z * Z)) (i : nat) (rest : list batch) (Σk : rtsA) (k : nat)
  (s : secst).
Hypothesis HOK : dl_ok p.
Hypothesis HWP : rt_wfP Σk ((b, skipn i ents) :: rest).
Hypothesis HS : dl_sig p Σk.
